-- q1 observabilidad del target en la entidad de alta por entidad y bucket
WITH j AS (SELECT c.entidad AS ent, CASE WHEN c.flg_clean = 1 THEN '1_clean' ELSE '2_dirty' END AS bucket, CAST(c.target_12m AS DOUBLE) AS tgt, CAST(c.target_03m AS DOUBLE) AS tgt3, CAST(c.target_06m AS DOUBLE) AS tgt6, c.pd_raw AS pd, CAST(c.filtro_madurez_blanda AS DOUBLE) AS blanda, CASE WHEN d.dias_atraso_12m IS NULL THEN 1e0 ELSE 0e0 END AS sin_dm12, CASE WHEN d.dias_atraso_6m IS NULL THEN 1e0 ELSE 0e0 END AS sin_dm06, CAST(d.falla_target_nulo AS DOUBLE) AS ciego, CAST(d.nro_miss12 AS DOUBLE) AS miss12, CASE WHEN d.clasificacion_m2 IS NULL THEN 1e0 ELSE 0e0 END AS invis_m2 FROM disc_model_owner.ds_adm_bpe_bankbn_cal c JOIN disc_model_owner.ds_adm_bpe_bankbn_drivers d ON CAST(c.codmes AS VARCHAR) = CAST(d.codmes AS VARCHAR) AND c.tip_doc = d.tip_doc AND c.key_value = d.key_value WHERE c.flg_calib = 1 AND c.flg_clean IN (0, 1)) SELECT ent, bucket, count(1) AS n, CAST(sum(tgt) AS BIGINT) AS malos, round(100e0 * avg(tgt), 2) AS badrate_pct, round(100e0 * avg(pd), 2) AS pd_media_pct, round(100e0 * approx_percentile(pd, 0.5), 2) AS pd_p50_pct, round(100e0 * avg(sin_dm12), 2) AS pct_sin_mora_observable_12m, round(100e0 * avg(sin_dm06), 2) AS pct_sin_mora_observable_6m, round(100e0 * avg(ciego), 2) AS pct_ciego_total, round(100e0 * avg(CASE WHEN miss12 = 12 THEN 1e0 ELSE 0e0 END), 2) AS pct_fuera_del_sistema, round(avg(miss12), 2) AS nro_miss12_prom, round(100e0 * avg(invis_m2), 2) AS pct_invisible_m2, round(100e0 * avg(blanda), 2) AS pct_madurez_blanda, CAST(sum(1e0 - sin_dm12) AS BIGINT) AS n_observados, round(100e0 * sum(CASE WHEN sin_dm12 = 0e0 THEN tgt ELSE 0e0 END) / nullif(sum(1e0 - sin_dm12), 0e0), 2) AS badrate_observados_pct, round(100e0 * sum(tgt3) / nullif(sum(tgt), 0e0), 1) AS pct_malos_ya_en_3m, round(100e0 * sum(tgt6) / nullif(sum(tgt), 0e0), 1) AS pct_malos_ya_en_6m FROM j GROUP BY ent, bucket ORDER BY ent, bucket
